ailable.'=>'L’extension a joint api.lotalytics.com. Les résultats sont mis en cache, et la dernière copie valide est affichée si le service est brièvement indisponible.','The game list came back empty.'=>'La liste des jeux est revenue vide.','Lottery results (Lotalytics)'=>'Résultats de loterie (Lotalytics)','The latest winning numbers of a lottery.'=>'Les derniers numéros gagnants d’une loterie.','Title (optional)'=>'Titre (facultatif)','Bonus'=>'Bonus','%s results'=>'Résultats %s','Winning numbers'=>'Numéros gagnants','Next draw: %s'=>'Prochain tirage : %s','Next %s draw'=>'Prochain tirage %s','block titleLottery results'=>'Résultats de loterie','block descriptionThe latest winning numbers of a lottery, with the next draw date.'=>'Les derniers numéros gagnants d’une loterie, avec la date du prochain tirage.','block keywordlottery'=>'loterie','block keywordlotto'=>'loto','block keywordresults'=>'résultats','block keywordwinning numbers'=>'numéros gagnants','block keywordpowerball'=>'powerball','block titleNext lottery draw'=>'Prochain tirage de loterie','block descriptionThe date of a lottery\'s next scheduled draw.'=>'La date du prochain tirage prévu d’une loterie.','block keywordnext draw'=>'prochain tirage','block keywordjackpot'=>'jackpot']];